import pathlib,json,re,hashlib
r=pathlib.Path('outputs/crazy-taxi-native');log=(r/'reports/guidance-history.log').read_text();assert not (r/'reports/guidance-history.err').read_text();assert 'PASS paced native input-only boarding and original passenger voice playback;' in log
counts=tuple(map(int,re.search(r'TIMESTAMPED GUIDANCE/SHADOW: guidance(\d+) shadow(\d+)',log).groups()));assert min(counts)>0
pose=json.loads((r/'reports/guidance-history-presentation-verification.json').read_text());assert pose['interior_blends']>20
report={'status':'PASS_HISTORICAL_GUIDANCE_SHADOW_RENDER_COVERAGE','guidance_draws':counts[0],'visible_shadow_queue_requests':counts[1],'pose_samples':pose['samples'],'interior_pose_blends':pose['interior_blends'],'binary_sha256':hashlib.sha256((r/'bin/scene-viewer-guidance-history.exe').read_bytes()).hexdigest(),'scope':'Bounded native input-only passenger pickup with shared traffic queue. Guidance eligibility/destination/angle/turn frame/scale read copied after-bracket history, palette distance uses sampled taxi position. Shadow projection already used sampled taxi/camera; sprite orientation now uses matching historical vehicle heading. Perdraw assertions preserve game/RNG/effect state plus current guidance angle/turn frame. Nonzero rendering branch coverage and numerical brackets, not independent original GPU pixel/framing/4K60 or complete HUD temporal fidelity proof.'}
(r/'reports/guidance-history-verification.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS guidance',counts[0],'shadow',counts[1])
